        (2, 1): 2, (2, 2): 4, (2, 3): 2, (2, 4): 4, (2, 5): 5,
        (2, 6): 1, (2, 7): 4, (2, 8): 2, (2, 9): 5,
        (3, 1): 4, (3, 2): 1, (3, 3): 1, (3, 4): 3, (3, 5): 3,
        (3, 6): 2, (3, 7): 4, (3, 8): 4, (3, 9): 3,
        (4, 1): 4, (4, 2): 4, (4, 3): 1, (4, 4): 3, (4, 5): 5,
        (4, 6): 3, (4, 7): 5, (4, 8): 1, (4, 9): 2,
        (5, 1): 4, (5, 2): 1, (5, 3): 4, (5, 4): 2, (5, 5): 2,
        (5, 6): 1, (5, 7): 2, (5, 8): 5, (5, 9): 2,
    },
    "demand": {
        1: 739, 2: 491, 3: 766, 4: 854, 5: 827,
        6: 908, 7: 434, 8: 605, 9: 480,
    },
    "capacity": {
        1: 1825, 2: 1821, 3: 1365, 4: 1929, 5: 1502,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.RangeSet(1, d["num_centers"])
    model.J = pyo.RangeSet(1, d["num_stores"])

    def transport_cost_init(m, i, j):
        return d["transport_cost"][(i, j)]

    def demand_init(m, j):
        return d["demand"][j]

    def capacity_init(m, i):
        return d["capacity"][i]

    def opening_cost_init(m, i):
        return d["opening_cost"][i]

    model.transport_cost = pyo.Param(model.I, model.J,
                                     initialize=transport_cost_init)
    model.demand = pyo.Param(model.J, initialize=demand_init)
    model.capacity = pyo.Param(model.I, initialize=capacity_init)
    model.opening_cost = pyo.Param(model.I, initialize=opening_cost_init)

    model.open_center = pyo.Var(model.I, within=pyo.Binary)
    model.ship = pyo.Var(model.I, model.J, within=pyo.NonNegativeReals)

    def obj_rule(m):
        opening = sum(m.opening_cost[i] * m.open_center[i] for i in m.I)
        shipping = sum(m.transport_cost[i, j] * m.ship[i, j]
                       for i in m.I for j in m.J)
        return opening + shipping

    model.obj = pyo.Objective(expr=obj_rule, sense=pyo.minimize)

    def demand_rule(m, j):
        return sum(m.ship[i, j] for i in m.I) >= m.demand[j]

    model.demand_satisfied = pyo.Constraint(model.J, rule=demand_rule)

    def capacity_rule(m, i):
        return sum(m.ship[i, j] for j in m.J) <= m.capacity[i] * m.open_center[i]

    model.capacity_limit = pyo.Constraint(model.I, rule=capacity_rule)

    return model
